{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.cluster_category_size_depth as WITH unique_pincode_mapping AS ( SELECT UPPER(state) AS state, pincode FROM snitch_db.maplemonk.gs_pincode_mapping_lat_long_tier QUALIFY ROW_NUMBER() OVER (PARTITION BY pincode ORDER BY state DESC) = 1 ), online_data AS ( SELECT upper(a.sku) as sku, upper(a.sku_group) as sku_group, case when upper(category) like \'%DENIM%\' then \'JEANS\' else upper(category) end as category, b.state, sum(a.quantity) as online_sales FROM snitch_db.maplemonk.fact_items_snitch a left join unique_pincode_mapping b on a.pincode::varchar = b.pincode::varchar WHERE LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%eco%\' AND LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%influ%\' AND LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%snitch_rms%\' AND order_name NOT IN (\'2431093\',\'2422140\',\'2425364\',\'2430652\',\'2422237\',\'2420623\',\'2429832\',\'2422378\',\'2428311\',\'2429064\',\'2428204\',\'2421343\',\'2431206\',\'2430491\',\'2426682\',\'2426487\',\'2426458\',\'2423575\',\'2422431\',\'2423612\',\'2426625\',\'2428117\',\'2426894\',\'2425461\',\'2426570\',\'2423455\',\'2430777\',\'2426009\',\'2428245\',\'2427269\',\'2430946\',\'2425821\',\'2429986\',\'2429085\',\'2422047\',\'2430789\',\'2420219\',\'2428341\',\'2430444\',\'2426866\',\'2431230\',\'2425839\',\'2430980\',\'2427048\',\'2430597\',\'2420499\',\'2431050\',\'2420271\',\'2426684\',\'2428747\',\'2423523\',\'2431171\',\'2430830\',\'2425325\',\'2428414\',\'2429054\',\'2423596\') AND tags NOT IN (\'FLITS_LOGICERP\') and lower(tags) not like \'%creator%\' group by 1,2,3,4 ), online_size_table AS ( SELECT SKU, STATE, CATEGORY, online_sales as sales, CASE WHEN SKU LIKE \'SN%\' OR SKU LIKE \'4MSFR%\' OR SKU LIKE \'BP%\' THEN \'NA\' WHEN SKU LIKE \'SH%\' THEN CASE WHEN SKU LIKE \'%-39\' THEN \'XS\' WHEN SKU LIKE \'%-40\' THEN \'S\' WHEN SKU LIKE \'%-41\' THEN \'M\' WHEN SKU LIKE \'%-42\' THEN \'L\' WHEN SKU LIKE \'%-43\' THEN \'XL\' WHEN SKU LIKE \'%-44\' THEN \'XXL\' WHEN SKU LIKE \'%-45\' THEN \'3XL\' END WHEN SKU LIKE \'4M%\' THEN CASE WHEN SKU LIKE \'%-XS\' OR SKU LIKE \'%-28\' THEN \'XS\' WHEN SKU LIKE \'%-S\' OR SKU LIKE \'%-30\' THEN \'S\' WHEN SKU LIKE \'%-M\' OR SKU LIKE \'%-32\' THEN \'M\' WHEN SKU LIKE \'%-L\' OR SKU LIKE \'%-34\' THEN \'L\' WHEN SKU LIKE \'%-XL\' OR SKU LIKE \'%-36\' THEN \'XL\' WHEN SKU LIKE \'%-XXL\' OR SKU LIKE \'%-38\' THEN \'XXL\' WHEN SKU LIKE \'%-3XL\' OR SKU LIKE \'%-40\' THEN \'3XL\' WHEN SKU LIKE \'%-4XL\' OR SKU LIKE \'%-42\' THEN \'4XL\' WHEN SKU LIKE \'%-5XL\' OR SKU LIKE \'%-44\' THEN \'5XL\' WHEN SKU LIKE \'%-6XL\' OR SKU LIKE \'%-46\' THEN \'6XL\' WHEN SKU LIKE \'%-7XL\' OR SKU LIKE \'%-48\' THEN \'7XL\' WHEN SKU LIKE \'%-8XL\' OR SKU LIKE \'%-50\' THEN \'8XL\' ELSE CASE WHEN POSITION(\'-\' IN SKU) > 0 THEN UPPER(TRIM(SUBSTRING(SKU, LEN(SKU) - CHARINDEX(\'-\', REVERSE(SKU)) + 2))) ELSE \'NA\' END END ELSE CASE WHEN POSITION(\'-\' IN SKU) > 0 THEN UPPER(TRIM(SUBSTRING(SKU, LEN(SKU) - CHARINDEX(\'-\', REVERSE(SKU)) + 2))) ELSE \'NA\' END END AS SIZE FROM online_data ), unique_branch_mapping AS ( SELECT a.\"STORE CODE\" AS BRANCH_CODE, UPPER(a.\"END BILLING\") AS STATE, ROW_NUMBER() OVER (PARTITION BY a.\"STORE CODE\" ORDER BY UPPER(a.\"END BILLING\")) AS rn FROM snitch_db.maplemonk.MASTER_FILE AS a ), offline_sales AS ( SELECT UPPER(a.SKU) AS SKU, upper(a.sku_group) as sku_group, b.STATE as state, sum(a.SHIPPING_QUANTITY) - sum(a.RETURN_QUANTITY) - sum(a.CANCELLED_QUANTITY) as offline_sales FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE AS a LEFT JOIN unique_branch_mapping AS b ON b.BRANCH_CODE = a.BRANCH_CODE WHERE b.rn = 1 group by 1,2,3 ), offline_Data AS ( SELECT a.sku as sku, a.sku_group as sku_group, a.state as state, a.offline_sales as offline_sales, upper(b.category) as category from offline_sales a left join snitch_db.maplemonk.category_journey b on a.sku_group = upper(b.sku_group) WHERE b.CATEGORY IS NOT NULL QUALIFY ROW_NUMBER() OVER (PARTITION BY a.sku_group ORDER BY category DESC) = 1 ), offline_size_table AS ( SELECT SKU, STATE, CATEGORY, OFFLINE_SALES AS SALES, CASE WHEN SKU LIKE \'SN%\' OR SKU LIKE \'4MSFR%\' OR SKU LIKE \'BP%\' THEN \'NA\' WHEN SKU LIKE \'SH%\' THEN CASE WHEN SKU LIKE \'%-39\' THEN \'XS\' WHEN SKU LIKE \'%-40\' THEN \'S\' WHEN SKU LIKE \'%-41\' THEN \'M\' WHEN SKU LIKE \'%-42\' THEN \'L\' WHEN SKU LIKE \'%-43\' THEN \'XL\' WHEN SKU LIKE \'%-44\' THEN \'XXL\' WHEN SKU LIKE \'%-45\' THEN \'3XL\' END WHEN SKU LIKE \'4M%\' THEN CASE WHEN SKU LIKE \'%-XS\' OR SKU LIKE \'%-28\' THEN \'XS\' WHEN SKU LIKE \'%-S\' OR SKU LIKE \'%-30\' THEN \'S\' WHEN SKU LIKE \'%-M\' OR SKU LIKE \'%-32\' THEN \'M\' WHEN SKU LIKE \'%-L\' OR SKU LIKE \'%-34\' THEN \'L\' WHEN SKU LIKE \'%-XL\' OR SKU LIKE \'%-36\' THEN \'XL\' WHEN SKU LIKE \'%-XXL\' OR SKU LIKE \'%-38\' THEN \'XXL\' WHEN SKU LIKE \'%-3XL\' OR SKU LIKE \'%-40\' THEN \'3XL\' WHEN SKU LIKE \'%-4XL\' OR SKU LIKE \'%-42\' THEN \'4XL\' WHEN SKU LIKE \'%-5XL\' OR SKU LIKE \'%-44\' THEN \'5XL\' WHEN SKU LIKE \'%-6XL\' OR SKU LIKE \'%-46\' THEN \'6XL\' WHEN SKU LIKE \'%-7XL\' OR SKU LIKE \'%-48\' THEN \'7XL\' WHEN SKU LIKE \'%-8XL\' OR SKU LIKE \'%-50\' THEN \'8XL\' ELSE CASE WHEN POSITION(\'-\' IN SKU) > 0 THEN UPPER(TRIM(SPLIT_PART(SKU, \'-\', -1))) ELSE \'NA\' END END ELSE CASE WHEN POSITION(\'-\' IN SKU) > 0 THEN UPPER(TRIM(SPLIT_PART(SKU, \'-\', -1))) ELSE \'NA\' END END AS SIZE FROM offline_data ), Combined_Size AS ( SELECT state, category, size, sales FROM online_size_table UNION ALL SELECT state, category, size, sales FROM offline_size_table ), final_size_table AS ( SELECT STATE, CATEGORY, SALES, CASE WHEN SIZE IN (\'28\', \'XS\') THEN \'XS\' WHEN SIZE IN (\'30\', \'S\') THEN \'S\' WHEN SIZE IN (\'32\', \'M\') THEN \'M\' WHEN SIZE IN (\'34\', \'L\') THEN \'L\' WHEN SIZE IN (\'36\', \'XL\') THEN \'XL\' WHEN SIZE IN (\'38\', \'XXL\') THEN \'XXL\' WHEN SIZE IN (\'40\', \'3XL\', \'XXXL\') THEN \'3XL\' WHEN SIZE IN (\'42\', \'XXXXL\', \'4XL\') THEN \'4XL\' WHEN SIZE IN (\'44\', \'5XL\') THEN \'5XL\' WHEN SIZE IN (\'46\', \'6XL\') THEN \'6XL\' WHEN SIZE IN (\'48\', \'7XL\') THEN \'7XL\' WHEN SIZE IN (\'50\', \'8XL\') THEN \'8XL\' ELSE \'NA\' END AS SIZE FROM combined_size ), size_sum as ( SELECT state, category, size, SUM(sales) AS total_sales FROM final_size_table GROUP BY state, category, size ), total_size_sum as ( select state, category, sum(total_sales) as total from size_sum group by state, category ), size_perc_table AS ( SELECT a.total, a.state, a.category, b.total_sales, b.size, b.total_sales / NULLIF(COALESCE(a.total, 0), 0) AS size_perc FROM size_sum AS b JOIN total_size_sum AS a ON a.state = b.state AND a.category = b.category ), final_data AS ( SELECT p.state, p.category, p.XS_PERC, p.S_PERC, p.M_PERC, p.L_PERC, p.XL_PERC, p.XXL_PERC, p.\"3XL_PERC\", p.\"4XL_PERC\", p.\"5XL_PERC\", p.\"6XL_PERC\", p.\"7XL_PERC\", p.\"8XL_PERC\", p.NA_PERC, s.\"STORE CODE\" AS BRANCH_CODE, s.\"STORE NAME\", s.DEPT_IDEAL FROM ( SELECT state, category, SUM(CASE WHEN size = \'XS\' THEN size_perc ELSE 0 END) AS XS_PERC, SUM(CASE WHEN size = \'S\' THEN size_perc ELSE 0 END) AS S_PERC, SUM(CASE WHEN size = \'M\' THEN size_perc ELSE 0 END) AS M_PERC, SUM(CASE WHEN size = \'L\' THEN size_perc ELSE 0 END) AS L_PERC, SUM(CASE WHEN size = \'XL\' THEN size_perc ELSE 0 END) AS XL_PERC, SUM(CASE WHEN size = \'XXL\' THEN size_perc ELSE 0 END) AS XXL_PERC, SUM(CASE WHEN size = \'3XL\' THEN size_perc ELSE 0 END) AS \"3XL_PERC\", SUM(CASE WHEN size = \'4XL\' THEN size_perc ELSE 0 END) AS \"4XL_PERC\", SUM(CASE WHEN size = \'5XL\' THEN size_perc ELSE 0 END) AS \"5XL_PERC\", SUM(CASE WHEN size = \'6XL\' THEN size_perc ELSE 0 END) AS \"6XL_PERC\", SUM(CASE WHEN size = \'7XL\' THEN size_perc ELSE 0 END) AS \"7XL_PERC\", SUM(CASE WHEN size = \'8XL\' THEN size_perc ELSE 0 END) AS \"8XL_PERC\", SUM(CASE WHEN size = \'NA\' THEN size_perc ELSE 0 END) AS NA_PERC FROM size_perc_table GROUP BY state, category ) AS p JOIN ( SELECT a.\"STORE CODE\", a.\"STORE NAME\", UPPER(TRIM(a.\"END BILLING\")) AS STATE, a.\"DOI BOH\" AS DEPT_IDEAL FROM snitch_db.maplemonk.master_file AS a ) AS s ON UPPER(p.state) = UPPER(s.state) ) SELECT BRANCH_CODE, STATE, CATEGORY, \"STORE NAME\", DEPT_IDEAL, XS_PERC, S_PERC, M_PERC, L_PERC, XL_PERC, XXL_PERC, \"3XL_PERC\", \"4XL_PERC\", \"5XL_PERC\", \"6XL_PERC\", \"7XL_PERC\", \"8XL_PERC\", ROUND(XS_PERC * DEPT_IDEAL) AS XS_DEPTH, ROUND(S_PERC * DEPT_IDEAL) AS S_DEPTH, ROUND(M_PERC * DEPT_IDEAL) AS M_DEPTH, ROUND(L_PERC * DEPT_IDEAL) AS L_DEPTH, ROUND(XL_PERC * DEPT_IDEAL) AS XL_DEPTH, ROUND(XXL_PERC * DEPT_IDEAL) AS XXL_DEPTH, ROUND(\"3XL_PERC\" * DEPT_IDEAL) AS \"3XL_DEPTH\", ROUND(\"4XL_PERC\" * DEPT_IDEAL) AS \"4XL_DEPTH\", ROUND(\"5XL_PERC\" * DEPT_IDEAL) AS \"5XL_DEPTH\", ROUND(\"6XL_PERC\" * DEPT_IDEAL) AS \"6XL_DEPTH\", ROUND(\"7XL_PERC\" * DEPT_IDEAL) AS \"7XL_DEPTH\", ROUND(\"8XL_PERC\" * DEPT_IDEAL) AS \"8XL_DEPTH\" FROM FINAL_DATA where category != \'NA\' ; create or replace table snitch_db.maplemonk.store_category_delta as with branch_details as ( select a.store as branch_name, a.store_code::varchar as branch_code, a.category, a.CLUSTER, b.\"BASE STOCK\" as base_stock, a.category_mix, a.category_mix*b.\"BASE STOCK\" as category_base_stock from snitch_db.maplemonk.category_mix a left join snitch_db.maplemonk.master_file b on upper(TRIM(a.store)) = upper(TRIM(b.\"STORE NAME\")) and upper(TRIM(a.store_code))::varchar = upper(TRIM(b.\"STORE CODE\"))::varchar and upper(TRIM(a.cluster)) = upper(TRIM(b.cluster)) ), inventory as ( select branch_code::varchar as branch_code, new_category as category, sum(inventory) as inventory, sum(jit_qty) as jit_qty, sum(fresh_inventory) as fresh_inv, sum(sales_last_7_days) as sales_7d, round(sum(sales_last_7_days)/7,0) as ros_7d from snitch_db.maplemonk.offline_master group by 1,2 ), lead_time as ( select BRANCH_CODE_PRIORITY::varchar as branch_code, lead_time from snitch_db.maplemonk.google_sheet_fresh_priority ), outward as ( SELECT STORE_CODE, CATEGORY, OUTWARD_QTY FROM SNITCH_DB.MAPLEMONK.CATEGORY_LEVEL_OUTWARD_OUTWARD_DATA ), fresh_in_jit as ( select category, TYPE as order_type, final_store, SUM(qty) as fresh_qty_jit from snitch_db.maplemonk.b2b_journey WHERE FINAL_STATUS NOT IN (\'INWARDED\') AND TYPE IN (\'FRESH ALLOCATION\') GROUP BY 1,2,3), cut_sizes as( SELECT branch_code, marketplace_mapped, COUNT_IF( inventory + jit_qty > 0 AND new_category IS NOT NULL ) AS total_skus, COUNT_IF( inventory + jit_qty > 0 AND new_category IS NOT NULL AND cut_size_with_jit_flag = \'Yes\' ) AS cut_size_skus, CASE WHEN COUNT_IF( inventory + jit_qty > 0 AND new_category IS NOT NULL ) = 0 THEN 0 ELSE ROUND( COUNT_IF( inventory + jit_qty > 0 AND new_category IS NOT NULL AND cut_size_with_jit_flag = \'Yes\' )::FLOAT / NULLIF( COUNT_IF( inventory + jit_qty > 0 AND new_category IS NOT NULL ), 0 ) , 4) END AS cut_size_pt FROM snitch_db.maplemonk.offline_master GROUP BY 1,2) , main_data as ( select a.*, ifnull(b.inventory,0) as inventory, ifnull(b.jit_qty,0) as jit_qty, ifnull(b.sales_7d,0) as sales_7d, ifnull(b.ros_7d,0) as ros_7d, ifnull(b.fresh_inv,0) as fresh_inv, ifnull(c.lead_time,0) as lead_time, ifnull (d.outward_qty,0) as outward_qty, ifnull (e.fresh_qty_jit,0) as fresh_qty_jit, ifnull(f.cut_size_pt,0) as cut_sizes from branch_details a left join inventory b on a.branch_code = b.branch_code and a.category = b.category left join lead_time c on a.branch_code = c.branch_code left join outward d on a.branch_code = d.store_code and a.category = d.category left join fresh_in_jit e on a.branch_name = e.final_store and a.category = e.category left join cut_sizes f on a.branch_code = f.branch_code ) select *, ifnull((inventory+jit_qty+(0.3*ros_7d)-(ros_7d*lead_time)-outward_qty),0) as total_inventory, ifnull((round(greatest((category_base_stock) - (inventory+jit_qty+(0.3*ros_7d)-(ros_7d*lead_time)-outward_qty),0),0)),0) as delta from main_data; create or replace table snitch_db.maplemonk.STORE_METAFIELD_DELTA2 as WITH base AS ( SELECT BRANCH_CODE AS BRANCH_CODE , NEW_CATEGORY AS NEW_CATEGORY , COLLAR_NEW , MATERIAL_NEW , SLEEVE_TYPE , FIT , DESIGNS , COALESCE(INVENTORY, 0) + COALESCE(JIT_QTY, 0) AS stock , COALESCE(TOTAL_SALES, 0) AS sales FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER ), totals AS ( SELECT BRANCH_CODE AS BRANCH_CODE , NEW_CATEGORY AS NEW_CATEGORY , SUM(stock) AS cat_stock_total , SUM(sales) AS cat_sales_total FROM base GROUP BY BRANCH_CODE , NEW_CATEGORY ) SELECT b.BRANCH_CODE AS BRANCH_CODE , b.NEW_CATEGORY AS NEW_CATEGORY , b.COLLAR_NEW AS COLLAR_NEW , b.MATERIAL_NEW AS MATERIAL_NEW , b.SLEEVE_TYPE AS SLEEVE_TYPE , b.FIT AS FIT , b.DESIGNS AS DESIGNS , SUM(b.stock) AS \"Inventory+JIT_Qty\" , SUM(b.stock) AS \"Stock\" , SUM(b.sales) AS \"Sales\" , CASE WHEN t.cat_stock_total = 0 THEN 0 ELSE (SUM(b.stock) / t.cat_stock_total) END AS \"Stock% at category level\" , CASE WHEN t.cat_sales_total = 0 THEN 0 ELSE (SUM(b.sales) / t.cat_sales_total) END AS \"Sales% at category level\" , CASE WHEN t.cat_stock_total = 0 OR t.cat_sales_total = 0 OR SUM(b.stock) = 0 THEN 0 ELSE GREATEST( 0, ( ( SUM(b.sales) / NULLIF(t.cat_sales_total, 0) ) / ( SUM(b.stock) / NULLIF(t.cat_stock_total, 0) ) ) * SUM(b.stock) - SUM(b.stock) ) END AS \"meta_delta\" FROM base b JOIN totals t ON b.BRANCH_CODE = t.BRANCH_CODE AND b.NEW_CATEGORY = t.NEW_CATEGORY GROUP BY b.BRANCH_CODE , b.NEW_CATEGORY , b.COLLAR_NEW , b.MATERIAL_NEW , b.SLEEVE_TYPE , b.FIT , b.DESIGNS , t.cat_stock_total , t.cat_sales_total ORDER BY b.BRANCH_CODE , b.NEW_CATEGORY , b.COLLAR_NEW , b.MATERIAL_NEW , b.SLEEVE_TYPE , b.FIT , b.DESIGNS ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            